import json, re, os
H = os.path.dirname(os.path.abspath(__file__))
def P(t): return f'<!-- wp:paragraph -->\n<p>{t}</p>\n<!-- /wp:paragraph -->\n\n'
def H2(t): return f'<!-- wp:heading -->\n<h2 class="wp-block-heading">{t}</h2>\n<!-- /wp:heading -->\n\n'
def UL(items):
    li = ''.join(f'<!-- wp:list-item -->\n<li>{i}</li>\n<!-- /wp:list-item -->' for i in items)
    return f'<!-- wp:list -->\n<ul class="wp-block-list">{li}</ul>\n<!-- /wp:list -->\n\n'
def A(slug, text): return f'<a href="https://dykhoa.com/blog/{slug}/">{text}</a>'
END = ('<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->\n\n'
       + P('<strong>Đôi lời giới thiệu</strong>')
       + P('Bài viết này viết dựa trên quan điểm của người viết, là Nguyễn Hoàng Anh Khoa (<a href="https://dykhoa.com/blog/dy-khoa-la-ai/">Dy Khoa</a>), giảng viên Khoa Quan hệ công chúng và Truyền thông, Trường Đại học Văn Lang, và là người tốt nghiệp Thạc sĩ Truyền thông Khoa học và Thu hút Công chúng (Science Communication and Public Engagement) tại Universiti Malaya (UM), Malaysia. Đây là lĩnh vực chuyên môn cốt lõi mà anh được đào tạo bài bản và tiếp tục theo đuổi trong nghiên cứu, giảng dạy và thực hành nghề nghiệp.')
       + P('Nếu bạn thấy bài viết có sai sót hoặc muốn góp ý, vui lòng gửi email về hi@dykhoa.com.'))
def REFS(refs):
    li = ''.join(f'<!-- wp:list-item -->\n<li>{r}</li>\n<!-- /wp:list-item -->' for r in refs)
    return f'<!-- wp:details {{"className":"dk-refs"}} -->\n<details class="wp-block-details dk-refs"><summary>Tài liệu tham khảo ({len(refs)} nguồn)</summary><!-- wp:list -->\n<ul class="wp-block-list">{li}</ul>\n<!-- /wp:list --></details>\n<!-- /wp:details -->'
HHT = 'Minh Thanh. (2026, ngày 25 tháng 8). Truyền thông khoa học: Nghề dành cho người mê khoa học và thích kể chuyện. <em>Hoa Học Trò, Báo điện tử Tiền Phong</em>. https://hoahoctro.tienphong.vn/truyen-thong-khoa-hoc-nghe-danh-cho-nguoi-me-khoa-hoc-va-thich-ke-chuyen-post1866220.tpo'
TN = 'Tran, M., &amp; Nguyen, A. (2023). Besieged from all sides: Impediments to science journalism in a developing country and their global implications. <em>Journal of Science Communication, 22</em>(4), A04. https://doi.org/10.22323/2.22040204'
TDT = 'Tran Dong Thai, H., Van Thuy Qui, H., Vu Duy, T., Fisher, J., &amp; Chambers, M. (2023). A study on biomedical researchers’ perspectives on public engagement in Southeast Asia. <em>Wellcome Open Research, 8</em>, 202. https://doi.org/10.12688/wellcomeopenres.19040.2'
BUL = 'Bullock, O. M., Colón Amill, D., Shulman, H. C., &amp; Dixon, G. N. (2019). Jargon as a barrier to effective science communication: Evidence from metacognition. <em>Public Understanding of Science, 28</em>(7), 845-853. https://doi.org/10.1177/0963662519865687 (bản mở: https://comm.osu.edu/sites/comm.osu.edu/files/PUS%202019-%20Bullock%20et%20al..pdf)'
