posts = []
# ---------- Bài 1
c = ''
c += P('Nếu bạn lên các trang tuyển dụng ở Việt Nam và gõ "truyền thông khoa học", rất có thể bạn sẽ thất vọng. Hiếm có tin nào ghi đúng chức danh ấy. Nhưng tôi tin đây là một nghề có thật, đang cần người, chỉ là nó mang nhiều tên gọi khác nhau.')
c += P('Khi trò chuyện với Hoa Học Trò về nghề này, tôi có nói rằng nhà tuyển dụng thường tuyển theo chức năng công việc, nên vị trí "Science Communicator" hiếm khi xuất hiện nguyên văn (Minh Thanh, 2026). Bài này là phần tôi muốn nói kỹ hơn: nghề ấy đang nằm ở đâu, và người muốn theo nghề cần chuẩn bị gì.')
c += H2('Nghề truyền thông khoa học đang "ẩn" ở đâu?')
c += P('Theo những gì tôi chia sẻ trong bài phỏng vấn, có ít nhất ba nơi người làm truyền thông khoa học có thể tìm thấy công việc của mình (Minh Thanh, 2026):')
c += UL([
    '<strong>Báo chí:</strong> phóng viên, biên tập viên mảng khoa học, sức khỏe, công nghệ, môi trường.',
    '<strong>Bệnh viện, doanh nghiệp dược, startup công nghệ y tế:</strong> các vị trí như Medical Writer, người viết nội dung sức khỏe hay chuyên viên truyền thông sức khỏe.',
    '<strong>Viện nghiên cứu, trường đại học, công ty công nghệ:</strong> bộ phận truyền thông, quan hệ công chúng hoặc truyền thông sản phẩm khoa học.',
])
c += P('Con đường của chính tôi cũng không mang một chức danh duy nhất. Tôi có nền tảng y sĩ đa khoa và báo chí, từng làm ở các startup công nghệ y tế như Doccen, Jio Health, Hello Bacsi, từng điều phối nhóm ứng phó khủng hoảng truyền thông, đào tạo cho bác sĩ, điều dưỡng, dược sĩ, học thạc sĩ chuyên ngành và hiện đứng lớp. Nhìn lại, điểm chung của những việc ấy là đưa kiến thức chuyên môn đến đúng người, theo cách họ hiểu và dùng được.')
c += H2('Trong nước có thật sự cần người làm nghề này?')
c += P('Tôi nghĩ là có, và các nghiên cứu ít ỏi hiện có cũng gợi ý như vậy. Một nghiên cứu phỏng vấn 40 nhà báo và biên tập viên khoa học Việt Nam cho thấy nghề báo khoa học gặp nhiều trở ngại, và nhóm tác giả ghi nhận đào tạo, hướng dẫn nghề nghiệp có thể tạo ra khác biệt đáng kể trong thời gian ngắn (Tran &amp; Nguyen, 2023).')
c += P('Ở phía nhà khoa học, khảo sát 70 nhà nghiên cứu y sinh cho thấy các rào cản được nêu nhiều nhất khi tham gia truyền thông với công chúng là thiếu năng lực (78,6%), thiếu hỗ trợ (70%) và thiếu thời gian (52,9%); 71,4% muốn có hội thảo rèn kỹ năng truyền thông khoa học (Tran Dong Thai và cộng sự, 2023). Cần nói rõ đây là các mẫu nhỏ, phần lớn nhà nghiên cứu thuộc một tổ chức, nên chưa thể khái quát cho cả hệ thống.')
c += P('Với tôi, khoảng trống đó chính là cơ hội: nhà khoa học cần người đồng hành để nói với công chúng, còn tòa soạn và doanh nghiệp cần người vừa đọc được nghiên cứu vừa viết được cho số đông. Bối cảnh chính sách về khoa học, công nghệ và đổi mới sáng tạo trong nước được phân tích kỹ hơn trong bài ' + A('truyen-thong-khoa-hoc-viet-nam-nghi-quyet-57', 'Truyền thông khoa học ở Việt Nam đang ở đâu sau Nghị quyết 57?') + '.')
c += H2('Muốn theo nghề, nên chuẩn bị gì?')
c += P('Những gì tôi khuyên trong bài phỏng vấn đến nay vẫn là điều tôi nói với người học (Minh Thanh, 2026):')
c += UL([
    '<strong>Đọc hiểu khoa học:</strong> biết đọc một nghiên cứu, hiểu cỡ mẫu, phương pháp, độ tin cậy của dữ liệu để không lan truyền điều chưa được kiểm chứng.',
    '<strong>Kể chuyện đa nền tảng:</strong> viết dài, viết cho mạng xã hội, làm video ngắn.',
    '<strong>Tiếng Anh:</strong> để đọc được nguồn khoa học gốc.',
    '<strong>Thực tế:</strong> thực tập, cộng tác với tòa soạn, bệnh viện, viện nghiên cứu hay doanh nghiệp công nghệ để có sản phẩm và mạng lưới.',
    '<strong>Đạo đức nghề:</strong> kiểm chứng, tôn trọng bằng chứng, và tách bạch truyền thông khoa học với quảng cáo trá hình.',
])
c += P('Nếu bạn đang phân vân có nên học thêm, bài ' + A('co-nen-hoc-thac-si-truyen-thong-khoa-hoc', 'Có nên học thạc sĩ truyền thông khoa học?') + ' và bài ' + A('hoc-truyen-thong-khoa-hoc-ra-truong-co-xin-duoc-viec-khong', 'Học truyền thông khoa học ra trường có xin được việc không?') + ' sẽ giúp bạn cân nhắc kỹ hơn.')
c += H2('Điều tôi muốn nói với người sắp vào nghề')
c += P('Đừng chờ một tin tuyển dụng ghi đúng chữ "truyền thông khoa học". Hãy nhìn vào việc mình có thể làm: biến một nghiên cứu thành câu chuyện đúng và dễ hiểu, giúp một bác sĩ nói rõ hơn với bệnh nhân, giúp một viện nghiên cứu được công chúng biết đến. Khi bạn làm tốt những việc đó, chức danh sẽ đến sau. Toàn bộ lộ trình học và làm nghề được tôi gom lại trong ' + HUB + '.')
